 jsonb_build_array('پوشش سناریوهای متنوع (آتش، مصدومیت، نشت، فضای محصور)','سناریوهای اختصاصی برای ریسک‌های ویژه پروژه (H2S، پرتو)','مسیر تخلیه، نقطه تجمع و مسئولیت‌های مشخص برای هر سناریو','تمرین دوره‌ای برنامه، نه فقط وجود سند مکتوب'),
